add_filter( 'woocommerce_checkout_fields', 'perfectpixel_labels_as_placeholders', 9999 );

function perfectpixel_labels_as_placeholders( $fields ) {
	$skip_types = array( 'select', 'country', 'state', 'checkbox', 'radio', 'hidden' );

	foreach ( $fields as $group => $group_fields ) {
		foreach ( $group_fields as $key => $field ) {
			if ( empty( $field['label'] ) || in_array( $field['type'] ?? 'text', $skip_types, true ) ) {
				continue;
			}
			$label = wp_strip_all_tags( $field['label'] );
			$fields[ $group ][ $key ]['placeholder'] = $label . ( ! empty( $field['required'] ) ? ' *' : '' );

			// Keep the label for screen readers, hide it visually.
			$classes   = isset( $field['label_class'] ) ? (array) $field['label_class'] : array();
			$classes[] = 'screen-reader-text';
			$fields[ $group ][ $key ]['label_class'] = $classes;
		}
	}

	return $fields;
}
